#!/usr/bin/env python3
# GENERATED by tools/sync_skills.py from shared/scripts/check_integration.py - edit the source, not this copy.
"""Scan an M-Pesa integration's source for the mistakes that lose money or double-pay.

Usage: python scripts/check_integration.py [path ...] [--json]
       (default path: the current directory)

Checks (heuristic: read each finding, don't apply blindly):
  paid-on-ack         order marked paid on ResponseCode "0" (that only means accepted)
  float-amount        amounts handled as floats/decimals; Daraja takes whole shillings
  receipt-not-unique  receipt stored without a UNIQUE constraint, so duplicate callbacks double-credit
  slow-callback       slow work (email, HTTP calls, sleeps) inside the callback handler before replying
  hardcoded-secret    consumer secret / passkey / initiator password written in source
  http-callback       a callback URL that is not HTTPS
Exit code 1 when any finding is "high".
"""
import json
import os
import re
import sys

CODE_EXT = {".py", ".js", ".mjs", ".cjs", ".ts", ".tsx", ".jsx", ".php", ".rb", ".go", ".java", ".kt", ".cs"}
SCHEMA_EXT = {".sql", ".prisma"}
SKIP_DIRS = {".git", "node_modules", ".venv", "venv", "__pycache__", "dist", "build", ".next", "vendor", "target"}

PAID_WORDS = re.compile(r"""(paid|completed?|success(ful)?|fulfil)""", re.I)
ACK = re.compile(r"""ResponseCode['"\]]*\s*(==|===|\.equals\(|eq)\s*['"]?0\b""")
FLOAT_AMOUNT = [
    re.compile(r"""\b(parseFloat|float|Decimal|toFixed)\s*\([^)]*amount""", re.I),
    re.compile(r"""['"]?Amount['"]?\s*[:=]\s*\d+\.\d+"""),
    re.compile(r"""amount\s+(DECIMAL|NUMERIC|FLOAT|DOUBLE|REAL)\b""", re.I),
    re.compile(r"""amount\s*[:=]?\s*(Float|Decimal|DOUBLE|models\.FloatField|models\.DecimalField)""", re.I),
]
# Parsing to float and then insisting on a whole number is validation, not float money.
WHOLE_CHECK = re.compile(r"""!=\s*int\(|is_integer\(|Number\.isInteger|%\s*1\b|Math\.floor\(|whole""", re.I)
RECEIPT_COL = re.compile(r"""(mpesa_?receipt(_?number)?|receipt_?number|MpesaReceiptNumber|transaction_?id)\b""", re.I)
UNIQUE = re.compile(r"""\bunique\b|@unique|UNIQUE\s*\(""", re.I)
CALLBACK_HINT = re.compile(r"""stkCallback|ResultCode|ResultURL|CallBackURL|/callback|confirmation""", re.I)
SLOW = re.compile(r"""\b(send_?mail|sendEmail|send_email|requests\.(get|post)|httpx\.(get|post)|axios\.|fetch\(|"""
                  r"""time\.sleep|sleep\(|smtp|twilio|send_?sms)""", re.I)
REPLY = re.compile(r"""(return\s+.*ResultCode|res\.(json|send|status)|JsonResponse|jsonify|Response\(|"""
                   r"""ResultDesc|response\(\)->json|c\.JSON)""", re.I)
SECRET = re.compile(r"""(consumer_?secret|consumerSecret|pass_?key|passKey|initiator_?password|initiatorPassword)"""
                    r"""\w*['"]?\s*[:=]\s*['"][A-Za-z0-9+/=_\-]{16,}['"]""", re.I)
HTTP_CB = re.compile(r"""(CallBackURL|ResultURL|QueueTimeOutURL|ConfirmationURL|ValidationURL|callback_?url)"""
                     r"""['"]?\s*[:=]\s*['"]http://(?!localhost|127\.0\.0\.1)""", re.I)

WHY = {
    "paid-on-ack": ("high", "ResponseCode \"0\" means Safaricom accepted the request, not that the customer paid.",
                    "Mark the order paid only when the callback (or STK Query / Transaction Status) has ResultCode 0."),
    "float-amount": ("medium", "Daraja amounts are whole shillings; floats round and drift.",
                     "Store integer shillings (or integer cents) and send an integer Amount."),
    "receipt-not-unique": ("high", "Safaricom can deliver a callback more than once; without a unique receipt "
                           "each copy credits the order again.",
                           "Add a UNIQUE constraint on the receipt (MpesaReceiptNumber) or CheckoutRequestID."),
    "slow-callback": ("medium", "Daraja expects a fast reply; slow handlers time out and trigger retries.",
                      "Store the raw callback, reply at once, and do emails/HTTP calls in a background job."),
    "hardcoded-secret": ("high", "Secrets in source end up in git history and logs.",
                         "Read them from environment variables or a secret store."),
    "http-callback": ("high", "Daraja only calls public HTTPS URLs.", "Use an https:// URL (a tunnel in development)."),
}


def files(paths):
    for root in paths:
        if os.path.isfile(root):
            yield root
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
            for name in filenames:
                ext = os.path.splitext(name)[1].lower()
                if ext in CODE_EXT or ext in SCHEMA_EXT:
                    yield os.path.join(dirpath, name)


def scan_file(path):
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            lines = fh.read().splitlines()
    except OSError:
        return []
    found = []
    text = "\n".join(lines)
    is_schema = os.path.splitext(path)[1].lower() in SCHEMA_EXT or re.search(r"CREATE TABLE", text, re.I) \
        or re.search(r"models\.Model\b|mongoose\.Schema\(|new Schema\(|@Entity\b|\.createTable\("
                     r"|sequelize\.define\(", text)
    callback_file = bool(CALLBACK_HINT.search(text))

    for i, line in enumerate(lines):
        window = "\n".join(lines[i:i + 6])
        if ACK.search(line) and PAID_WORDS.search(window) and "ResultCode" not in window.replace("ResponseCode", ""):
            found.append(("paid-on-ack", i))
        if any(p.search(line) for p in FLOAT_AMOUNT) and not WHOLE_CHECK.search("\n".join(lines[i:i + 3])):
            found.append(("float-amount", i))
        if SECRET.search(line):
            found.append(("hardcoded-secret", i))
        if HTTP_CB.search(line):
            found.append(("http-callback", i))
        if is_schema and RECEIPT_COL.search(line) and re.search(r"receipt", line, re.I):
            around = "\n".join(lines[max(0, i - 1):i + 2])
            table_unique = re.search(r"UNIQUE\s*\([^)]*receipt", text, re.I) or re.search(
                r"unique[^\n]*receipt|receipt[^\n]*unique", text, re.I)
            if not UNIQUE.search(around) and not table_unique:
                found.append(("receipt-not-unique", i))

    if callback_file:
        for i, line in enumerate(lines):
            if SLOW.search(line):
                after = "\n".join(lines[i + 1:i + 25])
                before = "\n".join(lines[max(0, i - 3):i + 1])
                if REPLY.search(after) and not re.search(
                        r"queue|enqueue|delay\(|background|celery|job|task|setImmediate", before, re.I):
                    found.append(("slow-callback", i))
                    break
    return [(check, path, i + 1, lines[i].strip()[:120]) for check, i in found]


def main(argv):
    as_json = "--json" in argv
    paths = [a for a in argv if a != "--json"] or ["."]
    findings = []
    seen = set()
    for path in files(paths):
        for check, file, line, text in scan_file(path):
            if (check, file, line) in seen:
                continue
            seen.add((check, file, line))
            level, why, fix = WHY[check]
            findings.append({"check": check, "level": level, "file": file, "line": line, "code": text,
                             "why": why, "fix": fix})
    findings.sort(key=lambda f: (f["level"] != "high", f["file"], f["line"]))
    if as_json:
        print(json.dumps(findings, indent=2))
    elif not findings:
        print("OK: no known M-Pesa integration mistakes found (these checks are heuristic, not a proof).")
    else:
        for f in findings:
            print(f"[{f['level'].upper()}] {f['check']}  {f['file']}:{f['line']}")
            print(f"    {f['code']}")
            print(f"    why: {f['why']}")
            print(f"    fix: {f['fix']}")
        high = sum(f["level"] == "high" for f in findings)
        print(f"\n{len(findings)} finding(s), {high} high.")
    return 1 if any(f["level"] == "high" for f in findings) else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
